module solitaire_merger (\n    input clk,\n    input rst_n,\n    input start,\n    \n    // Sequence A (max 4 elements, 8-bit values)\n    input [7:0] a0, a1, a2, a3,\n    input [2:0] len_a,\n    \n    // Sequence B (max 4 elements, 8-bit values)\n    input [7:0] b0, b1, b2, b3,\n    input [2:0] len_b,\n    \n    output reg [7:0] result,\n    output reg result_valid,\n    output reg done\n);\n\n    // Internal state\n    reg [2:0] state;\n    reg [2:0] ptr_a, ptr_b;\n    \n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPARE = 3'd1;\n    localparam [2:0] OUTPUT_A = 3'd2;\n    localparam [2:0] OUTPUT_B = 3'd3;\n    localparam [2:0] DONE = 3'd4;\n    \n    // Combinational comparison result\n    reg a_smaller;\n    \n    // Comparator logic as a always_comb block\n    always @* begin\n        // Defaults\n        a_smaller = 1'b1;\n        \n        // Handle empty sequences first\n        if (ptr_a >= len_a && ptr_b >= len_b) begin\n            a_smaller = 1'b1;  // They're equal, default tie-breaker for A\n        end\n        else if (ptr_a >= len_a) begin\n            a_smaller = 1'b1;  // A is done\n        end\n        else if (ptr_b >= len_b) begin\n            a_smaller = 1'b0;  // B is done\n        end\n        else begin\n            // Get current elements\n            logic [7:0] val_a;\n            logic [7:0] val_b;\n            \n            case (ptr_a)\n                3'd0: val_a = a0;\n                3'd1: val_a = a1;\n                3'd2: val_a = a2;\n                3'd3: val_a = a3;\n                default: val_a = 8'd0;\n            endcase\n            \n            case (ptr_b)\n                3'd0: val_b = b0;\n                3'd1: val_b = b1;\n                3'd2: val_b = b2;\n                3'd3: val_b = b3;\n                default: val_b = 8'd0;\n            endcase\n            \n            // Compare current\n            if (val_a < val_b) begin\n                a_smaller = 1'b1;\n            end\n            else if (val_a > val_b) begin\n                a_smaller = 1'b0;\n            end\n            else begin\n                // Equal - check next elements\n                logic next_ptra_valid = (ptr_a + 1 < len_a);\n                logic next_ptrb_valid = (ptr_b + 1 < len_b);\n                \n                if (next_ptra_valid & next_ptrb_valid) begin\n                    logic [7:0] next_a;\n                    logic [7:0] next_b;\n                    case (ptr_a + 1)\n                        3'd0: next_a = a0;\n                        3'd1: next_a = a1;\n                        3'd2: next_a = a2;\n                        3'd3: next_a = a3;\n                        default: next_a = 8'd0;\n                    endcase\n                    case (ptr_b + 1)\n                        3'd0: next_b = b0;\n                        3'd1: next_b = b1;\n                        3'd2: next_b = b2;\n                        3'd3: next_b = b3;\n                        default: next_b = 8'd0;\n                    endcase\n                    \n                    if (next_a < next_b) begin\n                        a_smaller = 1'b1;\n                    end\n                    else if (next_a > next_b) begin\n                        a_smaller = 1'b0;\n                    end\n                    else begin\n                        // Continue to check length available\n                        logic next_two_ptra_valid = (ptr_a + 2 < len_a);\n                        logic next_two_ptrb_valid = (ptr_b + 2 < len_b);\n                        \n                        if (next_two_ptra_valid & next_two_ptrb_valid) begin\n                            logic [7:0] next_next_a;\n                            logic [7:0] next_next_b;\n                            case (ptr_a + 2)\n                                3'd0: next_next_a = a0;\n                                3'd1: next_next_a = a1;\n                                3'd2: next_next_a = a2;\n                                3'd3: next_next_a = a3;\n                                default: next_next_a = 8'd0;\n                            endcase\n                            case (ptr_b + 2)\n                                3'd0: next_next_b = b0;\n                                3'd1: next_next_b = b1;\n                                3'd2: next_next_b = b2;\n                                3'd3: next_next_b = b3;\n                                default: next_next_b = 8'd0;\n                            endcase\n                            \n                            if (next_next_a < next_next_b) begin\n                                a_smaller = 1'b1;\n                            end\n                            else if (next_next_a > next_next_b) begin\n                                a_smaller = 1'b0;\n                            end\n                            else begin\n                                if ((len_a - ptr_a) < (len_b - ptr_b)) begin\n                                    a_smaller = 1'b1;\n                                end\n                                else begin\n                                    a_smaller = 1'b0;\n                                end\n                            end\n                        end\n                        else begin\n                            if ((len_a - ptr_a) < (len_b - ptr_b)) begin\n                                a_smaller = 1'b1;\n                            end\n                            else begin\n                                a_smaller = 1'b0;\n                            end\n                        end\n                    end\n                end\n                else begin\n                    if ((len_a - ptr_a) < (len_b - ptr_b)) begin\n                        a_smaller = 1'b1;\n                    end\n                    else begin\n                        a_smaller = 1'b0;\n                    end\n                end\n            end\n        end\n    end\n    \n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            ptr_a <= 3'd0;\n            ptr_b <= 3'd0;\n            result <= 8'd0;\n            result_valid <= 1'b0;\n            done <= 1'b0;\n        end\n        else begin\n            case (state)\n                IDLE: begin\n                    result_valid <= 1'b0;\n                    done <= 1'b0;\n                    if (start) begin\n                        ptr_a <= 3'd0;\n                        ptr_b <= 3'd0;\n                        state <= COMPARE;\n                    end\n                end\n                \n                COMPARE: begin\n                    result_valid <= 1'b0;\n                    if (ptr_a >= len_a && ptr_b >= len_b) begin\n                        state <= DONE;\n                    end\n                    else if (ptr_a >= len_a) begin\n                        state <= OUTPUT_B;\n                    end\n                    else if (ptr_b >= len_b) begin\n                        state <= OUTPUT_A;\n                    end\n                    else begin\n                        if (a_smaller) begin\n                            state <= OUTPUT_A;\n                        end\n                        else begin\n                            state <= OUTPUT_B;\n                        end\n                    end\n                end\n                \n                OUTPUT_A: begin\n                    case (ptr_a)\n                        3'd0: result <= a0;\n                        3'd1: result <= a1;\n                        3'd2: result <= a2;\n                        3'd3: result <= a3;\n                        default: result <= 8'd0;\n                    endcase\n                    result_valid <= 1'b1;\n                    ptr_a <= ptr_a + 1'd1;\n                    state <= COMPARE;\n                end\n                \n                OUTPUT_B: begin\n                    case (ptr_b)\n                        3'd0: result <= b0;\n                        3'd1: result <= b1;\n                        3'd2: result <= b2;\n                        3'd3: result <= b3;\n                        default: result <= 8'd0;\n                    endcase\n                    result_valid <= 1'b1;\n                    ptr_b <= ptr_b + 1'd1;\n                    state <= COMPARE;\n                end\n                \n                DONE: begin\n                    result_valid <= 1'b0;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n    \nendmodule